Lagged Specification - Individual Countries

# Load complete placebos dataset (lagged)
placebos_lags = pd.read_csv('data/complete_placebos_dataset_lags.csv')

# Define treatment years and effect year ranges for each country (lagged)
country_specs_lags = [
    ('AUT', 'Austria', 11, 2015, 2015, 2023, 'data/pvalues_AUTlags.csv'),   # Austria: treatment 2015, effects 2015-2023
    ('DEU', 'Germany', 13, 2015, 2015, 2023, 'data/pvalues_DEUlags.csv'),   # Germany: treatment 2015, effects 2015-2023
    ('SWE', 'Sweden', 15, 2013, 2013, 2023, 'data/pvalues_SWElags.csv')     # Sweden: treatment 2013, effects 2013-2023
]

for code, name, fig_num, treat_year, eff_start, eff_end, pval_file in country_specs_lags:
    # Get treated country data
    country_data = placebos_lags[(placebos_lags['code'] == code) & (placebos_lags['treated'] == 1)].copy()

    # Figure X: Synthetic control (with years on x-axis and treatment line)
    plot_synthetic_control_individual(country_data, code, f'{name} (Lagged) - Synthetic Control', 
                          os.path.join(output_dir, f'Fig{fig_num}_{code}_synth_lags.png'), 
                          use_years=True, treatment_year=treat_year)

    # Load p-values from Stata-generated CSV
    pvals_df = pd.read_csv(pval_file)
    # Create dictionary mapping year to p-value
    pvals = dict(zip(pvals_df['year'], pvals_df['pval']))

    # Figure X+1: Effects with standardized p-values (limited to treatment year onwards)
    plot_effects_with_pvalues(country_data, pvals, f'{name} (Lagged) - Treatment Effects', 
                             os.path.join(output_dir, f'Fig{fig_num+1}_{code}_effects_lags.png'), 
                             use_years=True, year_start=eff_start, year_end=eff_end)

